/**
 * NOC Contact Directory - Google Apps Script API
 *
 * Deploy as a Web App:
 *   Execute as: Me
 *   Who has access: Anyone
 */

const CONFIG = {
  ADMIN_SPREADSHEET_ID: '1HvCqLHC8IyllKskBXX1MtMfjQMGUyhMP7KuTuJxDhmU',
  ADMIN_SHEET_NAME: 'Admin Contact Details',
  ADMIN_RANGE: 'A2:N',

  DISTRICT_SPREADSHEET_ID: '1JxwLKphMWM9fqV43Tt0jQpQjlQC-6DaSlYQ66Fjq7rA',
  DISTRICT_SHEET_NAME: 'Data',
  DISTRICT_RANGE: 'A:I'
};

function doGet(e) {
  const action = e && e.parameter && e.parameter.action
    ? String(e.parameter.action)
    : 'getContacts';

  if (action !== 'getContacts') {
    return jsonOutput_({ success: false, error: 'Unsupported action: ' + action });
  }

  try {
    const adminRows = readSheet_(
      CONFIG.ADMIN_SPREADSHEET_ID,
      CONFIG.ADMIN_SHEET_NAME,
      CONFIG.ADMIN_RANGE
    );
    const officerRows = readSheet_(
      CONFIG.DISTRICT_SPREADSHEET_ID,
      CONFIG.DISTRICT_SHEET_NAME,
      CONFIG.DISTRICT_RANGE
    );

    return jsonOutput_({
      success: true,
      adminRows: adminRows,
      officerRows: officerRows,
      fetchedAt: new Date().toISOString()
    });
  } catch (err) {
    console.error(err && err.stack ? err.stack : err);
    return jsonOutput_({
      success: false,
      error: err && err.message ? err.message : String(err)
    });
  }
}

function readSheet_(spreadsheetId, sheetName, rangeA1) {
  const spreadsheet = SpreadsheetApp.openById(spreadsheetId);
  const sheet = spreadsheet.getSheetByName(sheetName);
  if (!sheet) {
    throw new Error('Sheet tab "' + sheetName + '" was not found in spreadsheet ' + spreadsheetId);
  }

  return sheet.getRange(rangeA1).getDisplayValues().filter(function(row) {
    return row.some(function(value) {
      return String(value).trim() !== '';
    });
  });
}

function jsonOutput_(payload) {
  return ContentService
    .createTextOutput(JSON.stringify(payload))
    .setMimeType(ContentService.MimeType.JSON);
}

// Optional manual test: run this once from the Apps Script editor.
function testContactData() {
  const admin = readSheet_(
    CONFIG.ADMIN_SPREADSHEET_ID,
    CONFIG.ADMIN_SHEET_NAME,
    CONFIG.ADMIN_RANGE
  );
  const district = readSheet_(
    CONFIG.DISTRICT_SPREADSHEET_ID,
    CONFIG.DISTRICT_SHEET_NAME,
    CONFIG.DISTRICT_RANGE
  );
  Logger.log('Admin rows: ' + admin.length);
  Logger.log('District rows: ' + district.length);
}
